  1106→ */
  1107→const FILE_EXTENSIONS = new Set([
  1108→  "yaml",
  1109→  "yml",
  1110→  "json",
  1111→  "js",
  1112→  "ts",
  1113→  "md",
  1114→  "txt",
  1115→  "html",
  1116→  "css",
  1117→  "log",
