  1266→// ============================================================
  1267→// AUTOMATION VALIDATION
  1268→// ============================================================
  1269→
  1270→/**
  1271→ * Check task automation status for warnings
  1272→ * AC: @task-automation-eligibility ac-21, ac-23
  1273→ */
  1274→function checkAutomationEligibility(
  1275→  tasks: LoadedTask[],
  1276→  index: ReferenceIndex,
  1277→): CompletenessWarning[] {
  1278→  const warnings: CompletenessWarning[] = [];
  1279→
  1280→  for (const task of tasks) {
  1281→    const taskRef = task.slugs?.[0]
  1282→      ? `@${task.slugs[0]}`
  1283→      : `@${task._ulid.slice(0, 8)}`;
  1284→
  1285→    // AC: @task-automation-eligibility ac-21
  1286→    // Warn if eligible but no spec_ref
  1287→    if (task.automation === "eligible" && !task.spec_ref) {
  1288→      warnings.push({
  1289→        type: "automation_eligible_no_spec",
  1290→        itemRef: taskRef,
  1291→        itemTitle: task.title,
  1292→        message: `Task ${taskRef} is automation: eligible but has no spec_ref - eligible tasks should have linked specs`,
  1293→      });
  1294→    }
  1295→
  1296→    // AC: @task-automation-eligibility ac-23
  1297→    // Warn if eligible but spec_ref doesn't resolve
  1298→    if (task.automation === "eligible" && task.spec_ref) {
  1299→      const specResult = index.resolve(task.spec_ref);
  1300→      if (!specResult.ok) {
  1301→        warnings.push({
  1302→          type: "automation_eligible_no_spec",
  1303→          itemRef: taskRef,
  1304→          itemTitle: task.title,
  1305→          message: `Task ${taskRef} is automation: eligible but spec_ref ${task.spec_ref} cannot be resolved`,
  1306→        });
  1307→      }
  1308→    }
  1309→  }
  1310→
  1311→  return warnings;
  1312→}
  1313→
  1314→// ============================================================
  1315→// MAIN VALIDATION
  1316→// ============================================================
  1317→
  1318→/**
  1319→ * Run full validation on a kspec project
  1320→ */
  1321→export async function validate(
  1322→  ctx: KspecContext,
  1323→  options: ValidateOptions = {},
  1324→): Promise<ValidationResult> {
  1325→  // Default: run all checks
  1326→  const runSchema = options.schema !== false;
  1327→  const runRefs = options.refs !== false;
  1328→  const runOrphans = options.orphans !== false;
  1329→  const runCompleteness = options.completeness !== false;
  1330→
  1331→  const result: ValidationResult = {
  1332→    valid: true,
  1333→    schemaErrors: [],
  1334→    refErrors: [],
  1335→    refWarnings: [],
  1336→    orphans: [],
  1337→    completenessWarnings: [],
  1338→    traitCycleErrors: [],
  1339→    stats: {
  1340→      filesChecked: 0,
  1341→      itemsChecked: 0,
  1342→      tasksChecked: 0,
  1343→    },
  1344→  };
  1345→
  1346→  const allTasks: LoadedTask[] = [];
  1347→  const allItems: LoadedSpecItem[] = [];
  1348→
  1349→  // Validate manifest
  1350→  if (ctx.manifestPath && runSchema) {
  1351→    const manifestErrors = await validateManifestFile(ctx.manifestPath);
  1352→    result.schemaErrors.push(...manifestErrors);
  1353→    result.stats.filesChecked++;
  1354→  }
  1355→
  1356→  // Load items from manifest (traits, inline modules, etc.)
  1357→  if (ctx.manifest && ctx.manifestPath) {
  1358→    const manifestItems = extractItemsFromRaw(ctx.manifest, ctx.manifestPath);
  1359→    allItems.push(...manifestItems);
  1360→    result.stats.itemsChecked += manifestItems.length;
  1361→  }
  1362→
  1363→  // Find and validate task files
  1364→  const taskFiles = await findTaskFiles(ctx.rootDir);
  1365→  const specTaskFiles = await findTaskFiles(path.join(ctx.rootDir, "spec"));
  1366→  const allTaskFiles = [...new Set([...taskFiles, ...specTaskFiles])];
  1367→
  1368→  for (const taskFile of allTaskFiles) {
  1369→    if (runSchema) {
  1370→      const taskErrors = await validateTasksFile(taskFile);
  1371→      result.schemaErrors.push(...taskErrors);
  1372→    }
  1373→    result.stats.filesChecked++;
  1374→
  1375→    // Load tasks for ref validation
  1376→    try {
  1377→      const raw = await readYamlFile<unknown>(taskFile);
  1378→      let taskList: unknown[] = [];
  1379→
  1380→      if (Array.isArray(raw)) {
  1381→        taskList = raw;
  1382→      } else if (raw && typeof raw === "object" && "tasks" in raw) {
  1383→        taskList = (raw as { tasks: unknown[] }).tasks || [];
  1384→      }
  1385→
  1386→      for (const t of taskList) {
  1387→        const parsed = TaskSchema.safeParse(t);
  1388→        if (parsed.success) {
  1389→          allTasks.push({ ...parsed.data, _sourceFile: taskFile });
  1390→          result.stats.tasksChecked++;
  1391→        }
  1392→      }
  1393→    } catch {
  1394→      // Already reported in schema validation
  1395→    }
  1396→  }
  1397→
  1398→  // Validate spec files (from includes)
  1399→  if (ctx.manifest && ctx.manifestPath) {
  1400→    const manifestDir = path.dirname(ctx.manifestPath);
  1401→    const includes = ctx.manifest.includes || [];
  1402→
  1403→    for (const include of includes) {
  1404→      const expandedPaths = await expandIncludePattern(include, manifestDir);
  1405→
  1406→      for (const filePath of expandedPaths) {
  1407→        if (runSchema) {
  1408→          const specErrors = await validateSpecFile(filePath);
  1409→          result.schemaErrors.push(...specErrors);
  1410→        }
  1411→        result.stats.filesChecked++;
  1412→
  1413→        // Load items for ref validation
  1414→        try {
  1415→          const items = await loadSpecFile(filePath);
  1416→          allItems.push(...items);
  1417→          result.stats.itemsChecked += items.length;
  1418→        } catch {
  1419→          // Already reported in schema validation
  1420→        }
  1421→      }
  1422→    }
  1423→  }
  1424→
  1425→  // Load meta items for reference validation
  1426→  // AC: @agent-definitions ac-agent-3
  1427→  const metaCtx = await loadMetaContext(ctx);
  1428→  const allMetaItems = [
  1429→    ...metaCtx.agents,
  1430→    ...metaCtx.workflows,
  1431→    ...metaCtx.conventions,
  1432→    ...metaCtx.observations,
  1433→  ];
  1434→
  1435→  // Load plans for reference validation
  1436→  // AC: @plan-validation ac-10
  1437→  const allPlans = await loadPlans(ctx);
  1438→
  1439→  // Reference validation
  1440→  if (
  1441→    runRefs &&
  1442→    (allTasks.length > 0 ||
  1443→      allItems.length > 0 ||
  1444→      allMetaItems.length > 0 ||
  1445→      allPlans.length > 0)
  1446→  ) {
  1447→    const index = new ReferenceIndex(
  1448→      allTasks,
  1449→      allItems,
  1450→      allMetaItems,
  1451→      allPlans,
  1452→    );
  1453→    const refResult = validateRefs(index, allTasks, allItems);
  1454→    result.refErrors = refResult.errors;
  1455→    result.refWarnings = refResult.warnings;
  1456→
  1457→    // AC: @trait-edge-cases ac-2
  1458→    // Detect circular trait references
  1459→    result.traitCycleErrors = detectTraitCycles(allItems, index);
  1460→
  1461→    // Orphan detection
  1462→    if (runOrphans) {
  1463→      result.orphans = findOrphans(allTasks, allItems, index);
  1464→    }
  1465→
  1466→    // Completeness validation
  1467→    // AC: @spec-completeness ac-1, ac-2, ac-3
  1468→    // AC: @trait-validation ac-3
  1469→    if (runCompleteness) {
  1470→      // Build trait index for trait AC coverage validation
  1471→      const traitIndex = new TraitIndex(allItems, index);
  1472→      result.completenessWarnings = await checkCompleteness(
  1473→        allItems,
  1474→        index,
  1475→        ctx.rootDir,
  1476→        traitIndex,
  1477→      );
  1478→
  1479→      // AC: @task-automation-eligibility ac-21, ac-23
  1480→      // Check automation eligibility warnings for tasks
  1481→      const automationWarnings = checkAutomationEligibility(allTasks, index);
  1482→      result.completenessWarnings.push(...automationWarnings);
  1483→    }
  1484→  }
  1485→
  1486→  // Meta manifest validation (AC-meta-manifest-2, AC-meta-manifest-3)
  1487→  const metaManifestPath = await findMetaManifest(ctx.specDir);
  1488→  if (metaManifestPath) {
  1489→    // Use metaCtx already loaded above
  1490→    result.metaStats = {
  1491→      agents: metaCtx.agents.length,
  1492→      workflows: metaCtx.workflows.length,
  1493→      conventions: metaCtx.conventions.length,
  1494→      observations: metaCtx.observations.length,
  1495→    };
  1496→
  1497→    // Validate meta manifest schema with strict ULID validation
  1498→    if (runSchema) {
  1499→      const metaErrors = await validateMetaManifestFile(metaManifestPath);
  1500→      // Prefix all meta errors with "meta:"
  1501→      for (const err of metaErrors) {
  1502→        err.path = err.path ? `meta:${err.path}` : "meta:";
  1503→      }
  1504→      result.schemaErrors.push(...metaErrors);
  1505→      result.stats.filesChecked++;
  1506→
  1507→      // AC: @skill-content-model ac-3 - validate skill content files exist
  1508→      if (metaCtx.skills.length > 0) {
  1509→        const skillContentErrors = await validateSkillContentFiles(ctx, metaCtx.skills);
  1510→        result.schemaErrors.push(...skillContentErrors);
  1511→      }
  1512→    }
  1513→  }
  1514→
  1515→  // Set valid flag
  1516→  result.valid =
  1517→    result.schemaErrors.length === 0 &&
  1518→    result.refErrors.length === 0 &&
  1519→    result.traitCycleErrors.length === 0;
  1520→
  1521→  return result;
  1522→}
