const { validate } = require('./dist/parser/validate.js');
const { initContext } = require('./dist/parser/yaml.js');
const fs = require('node:fs/promises');
const path = require('node:path');
const yaml = require('yaml');
const os = require('node:os');

async function test() {
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-test-'));

  // Create minimal manifest
  await fs.writeFile(path.join(tempDir, 'kynetic.yaml'), yaml.stringify({ kynetic: '1.0', includes: [] }));

  // Create skills directory with orphan
  const skillsDir = path.join(tempDir, 'skills', 'orphan-skill');
  await fs.mkdir(skillsDir, { recursive: true });
  await fs.writeFile(path.join(skillsDir, 'SKILL.md'), '# Orphan');

  // Create meta manifest with no skills
  const metaManifest = { kynetic_meta: '1.0', skills: [] };
  await fs.writeFile(path.join(tempDir, 'kynetic.meta.yaml'), yaml.stringify(metaManifest));

  const ctx = await initContext(tempDir);
  console.log('ctx.specDir:', ctx.specDir);
  const result = await validate(ctx);
  console.log('refWarnings count:', result.refWarnings.length);
  console.log('refWarnings:', JSON.stringify(result.refWarnings, null, 2));

  await fs.rm(tempDir, { recursive: true });
}
test().catch(console.error);
" 2>&1

